static inline int nvmem_cell_read(const struct nvmem_cell *cell, void *data, off_t off, size_t len)
{
	if (cell == NULL || !device_is_ready(cell->dev)) {
		return -ENODEV;
	}

	if (off < 0 || len == 0 || (off + len) > cell->size) {
		return -EINVAL;
	}

	const struct nvmem_driver_api *api = (const struct nvmem_driver_api *)cell->dev->api;

	if (api == NULL || api->read == NULL) {
		return -ENXIO;
	}

	return api->read(cell->dev, cell->offset + off, data, len);
}

